def in_L(s):
    z = 0
    i = 0
    while i < len(s) and s[i] == '0':
        z += 1
        i += 1
    o = len(s) - i
    if s[i:] != '1' * o:
        return False
    return z == o

count = 0
for i in range(4):
    xi = '0' * i
    ok = True
    for j in range(4):
        if j != i and in_L(xi + '1' * j):
            ok = False
    if in_L(xi + '1' * i) and ok:
        count += 1
print(count)

