def in_L(s):
    n = len(s) // 2
    return len(s) % 2 == 0 and s == '0' * n + '1' * n

def separates(i, j):
    return in_L('0' * i + '1' * i) and not in_L('0' * j + '1' * i)

classes = 0
for i in range(4):
    if all(i == j or separates(i, j) for j in range(4)):
        classes += 1
print(classes)
